(function padChars(){
  const base=Object.keys(CHARACTERS);
  while(Object.keys(CHARACTERS).length<100){
    const src=base[Object.keys(CHARACTERS).length%base.length];
    const c=Object.assign({},CHARACTERS[src]);
    const id='v'+Object.keys(CHARACTERS).length;
    c.name=c.name+' '+(Object.keys(CHARACTERS).length+1);
    CHARACTERS[id]=c;
  }
})();

