function applyUniqueSkillSets(){for(const [id,set] of Object.entries(UNIQUE_SKILL_SETS)){if(CHARACTERS[id]){CHARACTERS[id].sk1=set[0];CHARACTERS[id].sk2=set[1];CHARACTERS[id].ult=set[2];CHARACTERS[id].sk1.slot='SKILL';CHARACTERS[id].sk2.slot='SKILL 2';CHARACTERS[id].ult.slot='ULTIMATE';}}}
applyUniqueSkillSets();

