function getWorldTheme(stageIdx){
  const name=STAGE_MAP_NAMES[clamp(stageIdx|0,0,STAGE_MAP_NAMES.length-1)].toUpperCase();
  if(/SEA|KRAKEN|LAKE|RIVER|SWAMP|TURTLE ISLAND|JELLYFISH|CORAL|UNDERWATER|LEVIATHAN|HYDRA/.test(name))return'water';
  if(/ICE|SNOW|FROST|FROZEN/.test(name))return'snow';
  if(/LAVA|VOLCANO|FIRE REALM|MAGMA|HELLHOUND|DEMON|IMP CAVERN/.test(name))return'lava';
  if(/DESERT|SAND/.test(name))return'desert';
  if(/BAMBOO|NINJA|SAMURAI/.test(name))return'bamboo';
  if(/SKY|FLOATING|WIND|THUNDER|ZEUS|CELESTIAL|STORM QUEEN|LIGHT KING|FALLEN ANGEL|HARPY/.test(name))return'sky';
  if(/ROBOT|DRONE|ALIEN|MECHA|CHRONO|SHAPESHIFTER/.test(name))return'tech';
  if(/GRAVE|DEATH|NECROMANCER|TOMB|VOID|WRAITH|DARK|SHADOW|ECLIPSE|WARLOCK|HAUNTED/.test(name))return'shadow';
  if(/MUSHROOM|SPIDER/.test(name))return'mushroom';
  if(/RUIN|VILLAGE|CAMP|FORTRESS|OUTPOST|HIDEOUT|TEMPLE|CASTLE|TOWER|KEEP|PALACE|GATE|REALM/.test(name))return'ruins';
  if(/ROCK|MOUNTAIN|CAVE|CAVERN|CRYSTAL|NEST|LAIR|HILL|PASS/.test(name))return'rocky';
  if(/MEADOW/.test(name))return'meadow';
  return'forest';
}
